arguments.command:
cat > /tmp/merge.py <<'EOF'
import csv

def load(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

a = load('sales_a.csv')
b = load('sales_b.csv')

merged = {}
for row in a + b:
    rid = row['id']
    if rid not in merged or row['updated'] > merged[rid]['updated']:
        merged[rid] = row

header = ['id', 'region', 'amount', 'updated']
with open('merged.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=header)
    w.writeheader()
    for rid in sorted(merged, key=lambda x: int(x)):
        w.writerow(merged[rid])
EOF
python3 /tmp/merge.py && cat merged.csv

